		$tempo_gasto_segundos = $tempo_atual - $inicio_missao;
		$tempo_gasto_minutos = floor($tempo_gasto_segundos / 60);

		// Garantir que o tempo gasto seja pelo menos 1 minuto
		if($tempo_gasto_minutos < 1) $tempo_gasto_minutos = 1;

