/* Sistema de Banner de Invasão */
#banner-invasao {
    position: fixed;
    top: -100px;
    left: 0;
    right: 0;
    z-index: 9999;
    transition: transform 0.5s ease-in-out;
    font-family: Arial, sans-serif;
}

#banner-invasao.banner-visivel {
    transform: translateY(100px);
}

#banner-invasao.banner-saindo {
    transform: translateY(-100px);
}

.banner-invasao-container {
    background: linear-gradient(45deg, #ff4444, #cc0000);
    border-bottom: 3px solid #ffff00;
    box-shadow: 0 4px 15px rgba(0,0,0,0.5);
    animation: banner-pulse 2s infinite alternate;
}

.banner-invasao-container.inicio {
    background: linear-gradient(45deg, #ff4444, #cc0000);
}

.banner-invasao-container.fim {
    background: linear-gradient(45deg, #00aa00, #006600);
}

.banner-content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 15px 20px;
    max-width: 1200px;
    margin: 0 auto;
}

.banner-icon {
    font-size: 40px;
    margin-right: 15px;
    animation: banner-bounce 1s infinite;
}

.banner-text {
    flex: 1;
    color: white;
    text-shadow: 2px 2px 4px #000;
}

.banner-titulo {
    font-size: 24px;
    font-weight: bold;
    margin-bottom: 5px;
    text-transform: uppercase;
    letter-spacing: 2px;
}

.banner-descricao {
    font-size: 16px;
    line-height: 1.4;
}

.banner-descricao .premio {
    color: #ffff00;
    font-weight: bold;
}

.banner-descricao .bonus {
    color: #00ff00;
    font-weight: bold;
}

.banner-botoes {
    display: flex;
    gap: 10px;
    align-items: center;
}

.btn-participar, .btn-ver {
    background: linear-gradient(45deg, #ffff00, #ffcc00);
    color: #000;
    border: none;
    padding: 12px 20px;
    font-size: 14px;
    font-weight: bold;
    border-radius: 5px;
    cursor: pointer;
    text-transform: uppercase;
    transition: all 0.3s ease;
    border: 2px solid #000;
}

.btn-participar:hover, .btn-ver:hover {
    background: linear-gradient(45deg, #ffcc00, #ff9900);
    transform: scale(1.05);
}

.btn-fechar {
    background: rgba(0,0,0,0.5);
    color: white;
    border: none;
    padding: 8px 12px;
    font-size: 18px;
    font-weight: bold;
    border-radius: 50%;
    cursor: pointer;
    transition: all 0.3s ease;
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.btn-fechar:hover {
    background: rgba(255,0,0,0.7);
    transform: rotate(90deg);
}

/* Animações */
@keyframes banner-pulse {
    0% { box-shadow: 0 4px 15px rgba(0,0,0,0.5); }
    100% { box-shadow: 0 4px 25px rgba(255,255,0,0.8); }
}

@keyframes banner-bounce {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-5px); }
}

/* Banner rolante para texto longo */
.banner-descricao {
    overflow: hidden;
    white-space: nowrap;
}

.banner-invasao-container.inicio .banner-descricao,
.banner-invasao-container.fim .banner-descricao {
    animation: banner-scroll 15s linear infinite;
}

@keyframes banner-scroll {
    0% { transform: translateX(100%); }
    100% { transform: translateX(-100%); }
}

/* Responsividade */
@media (max-width: 768px) {
    .banner-content {
        flex-direction: column;
        text-align: center;
        gap: 10px;
    }

    .banner-titulo {
        font-size: 18px;
    }

    .banner-descricao {
        font-size: 14px;
        white-space: normal;
        animation: none;
    }

    .banner-botoes {
        justify-content: center;
    }
}

