_inc/mapa_chuva.php.content:
php
<?php
$logado = $_SESSION['logado'];
require_once('conexao.php');
require_once('funcoes_mapa.php');

// ID do mapa atual
$mapa_atual_id = 3;
$hide_ads = true;

if(!isset($_SESSION['logado'])) {
    header("Location: index.php?p=login");
    exit;
}

$stmt_admin = $conexao->prepare("SELECT adm FROM usuarios WHERE id = ?");
$stmt_admin->execute([$_SESSION['logado']]);
$user_admin = $stmt_admin->fetch(PDO::FETCH_ASSOC);
$is_admin = ($user_admin && ($user_admin['adm'] == 'sim' || $user_admin['adm'] == 1 || $user_admin['adm'] == 2));

// Criar tabelas se necessário
criarTabelasMapas($conexao);

if($is_admin && isset($_POST['admin_action'])) {
    header('Content-Type: application/json');
    ob_clean();

    switch($_POST['admin_action']) {
                                case 'add_icon':
            $vila = 4; // Vila da Chuva
            $nome = trim($_POST['nome']);
            $x = intval($_POST['x']);
            $y = intval($_POST['y']);
            $url = trim($_POST['url']);
            $descricao = trim($_POST['descricao']);
            $tipo_icone = trim($_POST['tipo_icone']) ?: 'normal';
            $mapa_destino = trim($_POST['mapa_destino']) ?: null;
            $x_destino = intval($_POST['x_destino']) ?: null;
            $y_destino = intval($_POST['y_destino']) ?: null;
            $cor_borda = trim($_POST['cor_borda']) ?: '#FFD700';
            $mapa_origem = trim($_POST['mapa_origem']) ?: null;
            $todos_podem_clicar = isset($_POST['todos_podem_clicar']) ? 1 : 0;

            if ($url && !empty($url)) {
                if (!str_starts_with($url, '?') && !str_starts_with($url, 'http')) {
                    if (!str_starts_with($url, 'p=')) {
                        $url = '?p=' . $url;
                    } else {
                        $url = '?' . $url;
                    }
                }
            }

            // Validar dados específicos para ícones de entrada/saída
            if($tipo_icone == 'entrada' && (!$mapa_destino || !$x_destino || !$y_destino)) {
                echo json_encode(['success' => false, 'message' => 'Ícones de entrada precisam de mapa e coordenadas de destino!']);
                exit;
            }

            if($tipo_icone == 'saida' && !$mapa_origem) {
                echo json_encode(['success' => false, 'message' => 'Ícones de saída precisam do mapa de origem!']);
                exit;
            }

            if($nome && $descricao && $x >= 1 && $x <= 20 && $y >= 1 && $y <= 20) {
                try {
                    $stmt = $conexao->prepare("INSERT INTO mapa_icones (vila, nome, x, y, url, descricao, tipo_icone, mapa_destino, x_destino, y_destino, cor_borda, mapa_origem, todos_podem_clicar) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
                    $stmt->execute([$vila, $nome, $x, $y, $url, $descricao, $tipo_icone, $mapa_destino, $x_destino, $y_destino, $cor_borda, $mapa_origem, $todos_podem_clicar]);
                    echo json_encode(['success' => true, 'message' => 'Ícone adicionado com sucesso!']);
                } catch(Exception $e) {
                    echo json_encode(['success' => false, 'message' => 'Erro ao salvar no banco: ' . $e->getMessage()]);
                }
            } else {
                echo json_encode(['success' => false, 'message' => 'Dados inválidos!']);
            }
            exit;
    }
}

$stmt = $conexao->prepare("SELECT x, y, floresta_x, floresta_y, floresta_mapa FROM usuarios WHERE id = ?");
$stmt->execute([$_SESSION['logado']]);
$user_position = $stmt->fetch(PDO::FETCH_ASSOC);

// Salvar que o jogador está no mapa da chuva (ID 4)
salvarJogadorNoMapa($conexao, $_SESSION['logado'], 4);

// Se está vindo da floresta, limpar dados da floresta e manter posição
if($user_position && $user_position['floresta_x'] !== null && $user_position['floresta_y'] !== null) {
    // Vindo da floresta - posicionar próximo ao ícone da floresta (18,18)
    $stmt = $conexao->prepare("UPDATE usuarios SET floresta_x = NULL, floresta_y = NULL, floresta_mapa = NULL, x = 17, y = 19 WHERE id = ?");
    $stmt->execute([$_SESSION['logado']]);
    $position = ['x' => 17, 'y' => 19];
} elseif(!$user_position || ($user_position['x'] === null || $user_position['y'] === null)) {
    // Posição inicial padrão
    $stmt = $conexao->prepare("UPDATE usuarios SET x = 17, y = 18 WHERE id = ?");
    $stmt->execute([$_SESSION['logado']]);
    $position = ['x' => 17, 'y' => 18];
} else {
    $position = $user_position;
}

// Buscar outros jogadores da Vila da Chuva (incluindo verificação de floresta)
$stmt = $conexao->prepare("
    SELECT u.id as player_id, u.usuario, u.avatar, u.personagem, u.x, u.y, u.vila, u.renegado
    FROM usuarios u 
    WHERE u.id != ? AND u.x IS NOT NULL AND u.y IS NOT NULL AND u.vila = 4 
    AND (u.floresta_x IS NULL OR u.floresta_y IS NULL OR u.floresta_mapa IS NULL)
");
$stmt->execute([$_SESSION['logado']]);
$other_players = $stmt->fetchAll(PDO::FETCH_ASSOC);

// Processar limpeza do mapa atual ao sair para floresta
if(isset($_POST['clear_mapa_atual'])) {
    $stmt = $conexao->prepare("UPDATE usuarios SET mapa_atual = NULL WHERE id = ?");
    $stmt->execute([$_SESSION['logado']]);
    exit;
}

if(isset($_POST['move_x']) && isset($_POST['move_y'])) {
    header('Content-Type: application/json');
    ob_clean();

    $new_x = intval($_POST['move_x']);
    $new_y = intval($_POST['move_y']);

    $distance = abs($new_x - $position['x']) + abs($new_y - $position['y']);
    if($distance <= 2 && $new_x >= 1 && $new_x <= 19 && $new_y >= 1 && $new_y <= 20) {
        try {
            // Garantir que as coordenadas da floresta sejam limpas e a posição do mapa seja salva
