<script>
let currentX = <?php echo $position['x']; ?>;
let currentY = <?php echo $position['y']; ?>;
let movendo = false;
let adminMode = false;
const isAdmin = <?php echo $is_admin ? 'true' : 'false'; ?>;

function moverPara(x, y) {
    if (movendo || x < 1 || x > 19 || y < 1 || y > 20) return;

    const distance = Math.abs(x - currentX) + Math.abs(y - currentY);
    if(distance === 0 || distance > 2) return;

    movendo = true;

    // Atualizar interface imediatamente para movimento fluido
    const oldX = currentX;
    const oldY = currentY;
    currentX = x;
    currentY = y;

    const playerElement = document.getElementById('player-self');
    if (playerElement) {
        playerElement.style.left = ((currentX - 1) * 32) + 'px';
        playerElement.style.top = ((currentY - 1) * 32) + 'px';
        playerElement.title = `Você - X:${currentX} Y:${currentY}`;
    }

    const formData = new FormData();
    formData.append('move_x', x);
    formData.append('move_y', y);

    fetch(window.location.pathname + '?p=mapa_chuva', {
        method: 'POST',
        body: formData,
        headers: {
            'X-Requested-With': 'XMLHttpRequest'
        }
    })
    .then(response => {
        if (!response.ok) {
            throw new Error('Erro na resposta: ' + response.status);
        }
        return response.text();
    })
    .then(text => {
        let data;
        try {
            data = JSON.parse(text);
        } catch (e) {
            // Se não for JSON, assumir sucesso (resposta HTML significa que funcionou)
            console.log('Movimento confirmado para:', currentX, currentY);

            // Atualizar coordenadas na interface
            const posicaoAtual = document.getElementById('posicao-atual');
            if (posicaoAtual) {
                posicaoAtual.innerHTML = `Posição Atual: X: ${currentX}, Y: ${currentY}`;
            }
            return;
        }

        if(data.success) {
            console.log('Movimento confirmado para:', currentX, currentY);

            // Atualizar coordenadas na interface
            const posicaoAtual = document.getElementById('posicao-atual');
            if (posicaoAtual) {
                posicaoAtual.innerHTML = `Posição Atual: X: ${currentX}, Y: ${currentY}`;
            }
        } else {
            // Reverter movimento se rejeitado
            console.error('Movimento rejeitado:', data.error || 'Erro desconhecido');
            currentX = oldX;
            currentY = oldY;
            if (playerElement) {
                playerElement.style.left = ((currentX - 1) * 32) + 'px';
                playerElement.style.top = ((currentY - 1) * 32) + 'px';
                playerElement.title = `Você - X:${currentX} Y:${currentY}`;
            }
            alert('Movimento inválido: ' + (data.error || 'Erro desconhecido'));
        }
    })
    .catch(error => {
        console.error('Erro ao mover:', error);
        // Reverter movimento em caso de erro de conexão
        currentX = oldX;
        currentY = oldY;
        if (playerElement) {
            playerElement.style.left = ((currentX - 1) * 32) + 'px';
            playerElement.style.top = ((currentY - 1) * 32) + 'px';
            playerElement.title = `Você - X:${currentX} Y:${currentY}`;
        }
        alert('Erro de conexão. Tente novamente.');
    })
    .finally(() => { 
        movendo = false; 
    });
}

document.addEventListener('keydown', function(e) {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;

    let newX = currentX;
    let newY = currentY;
    let moved = false;
    let distance = 2;

    switch(e.keyCode) {
        case 37: // Esquerda
            newX = Math.max(1, currentX - distance);
            moved = true;
            break;
        case 38: // Cima
            newY = Math.max(1, currentY - distance);
            moved = true;
            break;
        case 39: // Direita
            newX = Math.min(19, currentX + distance);
            moved = true;
            break;
        case 40: // Baixo
            newY = Math.min(20, currentY + distance);
            moved = true;
            break;
    }

    if (moved && (newX !== currentX || newY !== currentY)) {
        e.preventDefault();
        moverPara(newX, newY);
    }
});

