document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('.grid-cell').forEach(function(cell) {
        cell.addEventListener('dblclick', function(e) {
            e.preventDefault();
            moverPara(parseInt(this.getAttribute('data-x')), parseInt(this.getAttribute('data-y')));
        });
    });

    // Garantir foco para controles de teclado
    document.body.tabIndex =0;
    document.body.focus();
});

function clicarIconeEntrada(iconeX, iconeY, mapaDestino, xDestino, yDestino) {
    if (adminMode) return;

    const distanciaX = Math.abs(currentX - iconeX);
    const distanciaY = Math.abs(currentY - iconeY);

    if (distanciaX <= 1 && distanciaY <= 1) {
        sessionStorage.setItem('mapa_origem', window.location.search.match(/p=([^&]*)/)?.[1] || 'mapa');
        sessionStorage.setItem('x_origem', currentX);
        sessionStorage.setItem('y_origem', currentY);

        window.location.href = `?p=${mapaDestino}&destino_x=${xDestino}&destino_y=${yDestino}`;
    } else {
        alert('Você precisa estar ao lado do portal para usá-lo!');
    }
}

function clicarIconeSaida(iconeX, iconeY, mapaOrigem) {
    if (adminMode) return;

    const distanciaX = Math.abs(currentX - iconeX);
    const distanciaY = Math.abs(currentY - iconeY);

    if (distanciaX <= 1 && distanciaY <= 1) {
        const origemX = sessionStorage.getItem('x_origem') || 10;
        const origemY = sessionStorage.getItem('y_origem') || 10;

        sessionStorage.removeItem('mapa_origem');
        sessionStorage.removeItem('x_origem');
        sessionStorage.removeItem('y_origem');

        window.location.href = `?p=${mapaOrigem}&destino_x=${origemX}&destino_y=${origemY}`;
    } else {
        alert('Você precisa estar ao lado da saída para usá-la!');
    }
}

function toggleTipoIcone(tipo) {
    const entradaFields = document.getElementById('entrada-fields');
    const saidaFields = document.getElementById('saida-fields');
    if (tipo === 'entrada') {
        entradaFields.style.display = 'flex';
        saidaFields.style.display = 'none';
    } else if (tipo === 'saida') {
        entradaFields.style.display = 'none';
        saidaFields.style.display = 'block';
    } else {
        entradaFields.style.display = 'none';
        saidaFields.style.display = 'none';
    }
}
</script>

