// Sistema de Banner de Invasão
var BannerInvasao = {
    bannerAtivo: false,

    // Verificar se há banners para exibir
    verificarBanners: function() {
        if (this.bannerAtivo) return; // Já há um banner ativo

        fetch('_inc/check_banner_invasao.php')
            .then(response => response.json())
            .then(data => {
                if (data.mostrar_banner) {
                    this.exibirBanner(data);
                }
            })
            .catch(error => {
                console.log('Erro ao verificar banners:', error);
            });
    },

    // Exibir banner
    exibirBanner: function(data) {
        if (this.bannerAtivo) return;

        this.bannerAtivo = true;

        // Criar elemento do banner
        var banner = document.createElement('div');
        banner.id = 'banner-invasao';
        banner.innerHTML = this.gerarHTMLBanner(data);

        // Adicionar ao topo da página
        document.body.insertBefore(banner, document.body.firstChild);

        // Aplicar animação de entrada
        setTimeout(() => {
            banner.classList.add('banner-visivel');
        }, 100);

        // Auto-fechar após 10 segundos
        setTimeout(() => {
            this.fecharBanner(data.invasao_id, data.tipo);
        }, 10000);
    },

    // Gerar HTML do banner baseado no tipo
    gerarHTMLBanner: function(data) {
        var html = '';

        if (data.tipo === 'inicio') {
            html = `
                <div class="banner-invasao-container inicio">
                    <div class="banner-content">
                        <div class="banner-icon">🔥</div>
                        <div class="banner-text">
                            <div class="banner-titulo">INVASÃO COMEÇOU!</div>
                            <div class="banner-descricao">
                                <strong>${data.nome_invasor}</strong> está atacando! 
                                Prêmio: <span class="premio">${data.premio_yens} Yens</span> | 
                                Bônus Vila: <span class="bonus">+${data.bonus_vila}%</span>
                            </div>
                        </div>
                        <div class="banner-botoes">
                            <button onclick="window.location.href='?p=invasao'" class="btn-participar">⚔️ PARTICIPAR</button>
                            <button onclick="BannerInvasao.fecharBanner(${data.invasao_id}, '${data.tipo}')" class="btn-fechar">✕</button>
                        </div>
                    </div>
                </div>
            `;
        } else if (data.tipo === 'fim') {
            html = `
                <div class="banner-invasao-container fim">
                    <div class="banner-content">
                        <div class="banner-icon">🏆</div>
                        <div class="banner-text">
                            <div class="banner-titulo">INVASÃO DERROTADA!</div>
                            <div class="banner-descricao">
                                <strong>${data.vencedor_nome}</strong> derrotou <strong>${data.nome_invasor}</strong>!<br>
                                Prêmio: <span class="premio">${data.premio_yens} Yens</span> | 
                                Vila <strong>${data.vila_vencedora}</strong> ganhou <span class="bonus">+${data.bonus_vila}%</span> em todos os status!
                            </div>
                        </div>
                        <div class="banner-botoes">
                            <button onclick="window.location.href='?p=invasao'" class="btn-ver">👁️ VER RESULTADO</button>
                            <button onclick="BannerInvasao.fecharBanner(${data.invasao_id}, '${data.tipo}')" class="btn-fechar">✕</button>
                        </div>
                    </div>
                </div>
            `;
        }

        return html;
    },

    // Fechar banner e marcar como visualizado
    fecharBanner: function(invasaoId, tipo) {
        var banner = document.getElementById('banner-invasao');
        if (banner) {
            banner.classList.remove('banner-visivel');
            banner.classList.add('banner-saindo');

            setTimeout(() => {
                banner.remove();
                this.bannerAtivo = false;
            }, 500);

            // Marcar como visualizado no servidor
            this.marcarComoVisualizado(invasaoId, tipo);
        }
    },

    // Marcar banner como visualizado
    marcarComoVisualizado: function(invasaoId, tipo) {
        fetch('_inc/marcar_banner_visualizado.php', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                invasao_id: invasaoId,
                tipo: tipo
            })
        });
    }
};

// Verificar banners ao carregar a página
document.addEventListener('DOMContentLoaded', function() {
    BannerInvasao.verificarBanners();
});

// Verificar banners periodicamente (a cada 30 segundos)
setInterval(function() {
    BannerInvasao.verificarBanners();
}, 30000);

