#popup-noticia-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.8);
    z-index: 9998;
}

#popup-noticia {
    display: none;
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 500px;
    height: 600px;
    z-index: 9999;
}

#popup-noticia-content {
    width: 100%;
    height: 100%;
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

#popup-noticia-pergaminho {
    position: relative;
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
}

#popup-noticia-pergaminho img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    animation: abrirPergaminho 1.2s ease-out forwards;
    transform-origin: center center;
}

@keyframes abrirPergaminho {
    0% {
        transform: scaleX(0.2) scaleY(0.8);
        opacity: 0.5;
    }
    50% {
        transform: scaleX(0.6) scaleY(0.9);
        opacity: 0.8;
    }
    100% {
        transform: scaleX(1) scaleY(1);
        opacity: 1;
    }
}

#popup-noticia-titulo {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -80%);
    color: #FFD700;
    font-size: 48px;
    font-weight: bold;
    text-align: center;
    text-shadow: 
        -2px -2px 0 #000,
        2px -2px 0 #000,
        -2px 2px 0 #000,
        2px 2px 0 #000,
        -3px 0 0 #000,
        3px 0 0 #000,
        0 -3px 0 #000,
        0 3px 0 #000,
        0 0 10px rgba(0, 0, 0, 0.8);
    z-index: 10;
    pointer-events: none;
    opacity: 0;
    animation: aparecerTexto 0.6s ease-in forwards;
    animation-delay: 1s;
}

@keyframes aparecerTexto {
    0% {
        opacity: 0;
        transform: translate(-50%, -80%) scale(0.5);
    }
    100% {
        opacity: 1;
        transform: translate(-50%, -80%) scale(1);
    }
}

#popup-noticia-botao {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, 20%);
    background: transparent;
    border: none;
    cursor: pointer;
    color: #FFD700;
    font-size: 20px;
    font-weight: bold;
    text-decoration: underline;
    text-shadow: 
        -2px -2px 0 #000,
        2px -2px 0 #000,
        -2px 2px 0 #000,
        2px 2px 0 #000,
        -3px 0 0 #000,
        3px 0 0 #000,
        0 -3px 0 #000,
        0 3px 0 #000,
        0 0 5px rgba(0, 0, 0, 0.8);
    padding: 10px 20px;
    z-index: 10;
    opacity: 0;
    animation: aparecerBotao 0.6s ease-in forwards;
    animation-delay: 1.2s;
}

@keyframes aparecerBotao {
    0% {
        opacity: 0;
        transform: translate(-50%, 20%) scale(0.5);
    }
    100% {
        opacity: 1;
        transform: translate(-50%, 20%) scale(1);
    }
}

#popup-noticia-botao:hover {
    color: #FFA500;
    text-shadow: 
        -2px -2px 0 #000,
        2px -2px 0 #000,
        -2px 2px 0 #000,
        2px 2px 0 #000,
        -3px 0 0 #000,
        3px 0 0 #000,
        0 -3px 0 #000,
        0 3px 0 #000,
        0 0 8px rgba(255, 165, 0, 0.8);
}

@media (max-width: 768px) {
    #popup-noticia {
        width: 90%;
        height: auto;
        max-height: 90vh;
    }

    #popup-noticia-content {
        min-height: 400px;
    }

    #popup-noticia-titulo {
        font-size: 32px;
    }

    #popup-noticia-botao {
        font-size: 16px;
    }
}

